```cpp
#include <iostream>
#include <string>

std::string markdownToHtml(const std::string &markdown) {
    std::string html;

    // Rules for conversion:
    // * Headers become h1, h2 tags
    // * Bold text becomes <b>
    // * Italic text becomes <i>
    // * Links become anchor tags

    for(int i = 0; i < markdown.length(); i++) {
        if(markdown[i] == '#') {
            if(markdown[i+1] == '#')
                html += "<h2>";
            else 
                html += "<h1>";
        }
        else if(markdown[i] == '*' && markdown[i+1] != ' ')
            html += markdown[i+1] == '*' ? "</b>" : "<b>";
        else if(markdown[i] == '_' && markdown[i+1] != ' ') 
            html += markdown[i+1] == '_' ? "</i>" : "<i>";
        else if(markdown[i] == '[' && markdown[i+1] != ' ') 
            html += "<a href=\"";
        else if(markdown[i] == ']' && markdown[i-1] != ' ')
            html += "\">";
        else
            html += markdown[i];
    }

    return html;
}
```

This iterates through the markdown string and applies rules to convert formatting like headers, bold, italics, and links into their HTML tag equivalents. It returns the resulting HTML string.

